package dev.hrutvik.billing.outbox;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="outbox_events")
public class OutboxEvent { @Id private UUID id; @Column(name="aggregate_id") private UUID aggregateId; @Column(name="event_type") private String eventType; @Column(name="tenant_id") private String tenantId; private String destination; @Column(columnDefinition="text") private String payload; @Column(name="created_at") private Instant createdAt; @Column(name="published_at") private Instant publishedAt; @Column(name="leased_until") private Instant leasedUntil; @Column(name="lease_owner") private String leaseOwner; @Column(name="publish_attempts") private int publishAttempts; protected OutboxEvent(){} public OutboxEvent(UUID id,UUID aggregateId,String eventType,String tenantId,String payload,Instant createdAt){this(id,aggregateId,eventType,tenantId,null,payload,createdAt);} public OutboxEvent(UUID id,UUID aggregateId,String eventType,String tenantId,String destination,String payload,Instant createdAt){this.id=id;this.aggregateId=aggregateId;this.eventType=eventType;this.tenantId=tenantId;this.destination=destination;this.payload=payload;this.createdAt=createdAt;} public UUID getId(){return id;} public UUID getAggregateId(){return aggregateId;} public String getEventType(){return eventType;} public String getTenantId(){return tenantId;} public String getDestination(){return destination;} public String getPayload(){return payload;} public void lease(String owner,Instant until){leaseOwner=owner;leasedUntil=until;publishAttempts++;} public void published(Instant at){publishedAt=at;leaseOwner=null;leasedUntil=null;} public void release(){leaseOwner=null;leasedUntil=null;} public int getPublishAttempts(){return publishAttempts;} }
